Trang 244 | CHƯƠNG 5 | Các khối chức năng kỹ thuật số

Ví dụ HDL 5.1: BỘ CỘNG LAN TRUYỀN NHỚ (CPA - CARRY PROPAGATE ADDER)

[Mã SystemVerilog]
module adder #(parameter N = 8)
    (input logic [N-1:0] a, b,
     input logic cin,
     output logic [N-1:0] s,
     output logic cout);
  assign {cout, s} = a + b + cin;
endmodule

[Mã VHDL]
library IEEE; use IEEE.STD_LOGIC_1164.ALL;
use IEEE.NUMERIC_STD_UNSIGNED.ALL;

entity adder is
  generic(N: integer := 8);
  port(a, b: in STD_LOGIC_VECTOR(N-1 downto 0);
       cin: in STD_LOGIC;
       s: out STD_LOGIC_VECTOR(N-1 downto 0);
       cout: out STD_LOGIC);
end;

architecture synth of adder is
  signal result: STD_LOGIC_VECTOR(N downto 0);
begin
  result <= ("0" & a) + ("0" & b) + cin;
  s <= result(N-1 downto 0);
  cout <= result(N);
end;

Hình 5.8: Bộ cộng sau khi tổng hợp phần cứng (Synthesized adder)

... chọn thiết kế rẻ nhất (kích thước nhỏ nhất) đáp ứng được các yêu cầu về tốc độ. Điều này đơn giản hóa đáng kể công việc của nhà thiết kế. Ví dụ HDL 5.1 mô tả một bộ CPA với các tín hiệu nhớ đầu vào (cin) và đầu ra (cout), và Hình 5.8 hiển thị phần cứng kết quả.

5.2.2 Phép trừ (Subtraction)
Hãy nhớ lại từ Mục 1.4.6 rằng các bộ cộng có thể cộng số dương và số âm bằng cách sử dụng biểu diễn bù 2 (two’s complement). Phép trừ cũng gần như dễ dàng tương tự: đảo dấu (tức là đổi ngược lại) của số thứ hai, sau đó thực hiện phép cộng. Việc đảo dấu của một số bù 2 được thực hiện bằng cách đảo ngược tất cả các bit và cộng thêm 1.

Để tính $Y = A - B$, trước tiên hãy tạo số bù 2 của $B$: đảo các bit của $B$ để thu được $\bar{B}$ và cộng 1 để có $-B = \bar{B} + 1$. Cộng lượng này vào $A$ để thu được $Y = A + \bar{B} + 1 = A - B$. Phép tổng này có thể được thực hiện với một bộ CPA duy nhất bằng cách cộng $A + \bar{B}$ với tín hiệu nhớ đầu vào $C_{in} = 1$. Hình 5.9 hiển thị ký hiệu cho một bộ trừ và phần cứng cốt lõi bên dưới để thực hiện $Y = A - B$. Ví dụ HDL 5.2 mô tả bộ trừ và Hình 5.10 hiển thị phần cứng kết quả thu được.

Hình 5.9 Bộ trừ: (a) ký hiệu, (b) hiện thực phần cứng (implementation)

5.2 Mạch Số Học | 245

HDL Ví dụ 5.2 MẠCH TRỪ

SystemVerilog
module subtractor #(parameter N = 8)
                 (input logic [N-1:0] a, b,
                  output logic [N-1:0] y);
  assign y = a - b;
endmodule

VHDL
library IEEE; use IEEE.STD_LOGIC_1164.ALL;
use IEEE.NUMERIC_STD_UNSIGNED.ALL;

entity subtractor is
  generic(N: integer := 8);
  port(a, b: in STD_LOGIC_VECTOR(N-1 downto 0);
       y: out STD_LOGIC_VECTOR(N-1 downto 0));
end;

architecture synth of subtractor is
begin
  y <= a - b;
end;

Hình 5.10 Mạch trừ sau khi tổng hợp

Hình 5.11 Bộ so sánh bằng 4-bit: (a) ký hiệu, (b) sơ đồ thực thi

5.2.3 Bộ so sánh (Comparators)
Bộ so sánh (comparator) xác định xem hai số nhị phân có bằng nhau hay không, hoặc số này lớn hơn hay nhỏ hơn số kia. Một bộ so sánh nhận hai số nhị phân N-bit A và B làm đầu vào và xuất ra kết quả so sánh 1-bit.
Bộ so sánh bằng (equality comparator) tạo ra một đầu ra duy nhất, chỉ ra liệu A có bằng B (A == B) hay không. Bộ so sánh giá trị (magnitude comparator) tạo ra một hoặc nhiều đầu ra, chỉ ra giá trị tương quan giữa A và B.
Bộ so sánh bằng là khối phần cứng đơn giản hơn. Hình 5.11 trình bày ký hiệu và sơ đồ thực thi của bộ so sánh bằng 4-bit. Đầu tiên, nó kiểm tra để xác định xem các bit tương ứng ở từng vị trí cột của A và B có bằng nhau không bằng cách dùng các cổng XNOR. Hai số bằng nhau nếu tất cả các cột đều bằng nhau.

246 | CHƯƠNG NĂM | Khối Xây Dựng Số (Digital Building Blocks)

So sánh độ lớn của các số có dấu thường được thực hiện bằng cách tính A – B và quan sát bit dấu (bit có trọng số lớn nhất - MSB) của kết quả như mô tả trong Hình 5.12. Nếu kết quả là số âm (tức là bit dấu bằng 1), thì A nhỏ hơn B. Ngược lại, A lớn hơn hoặc bằng B. Tuy nhiên, bộ so sánh này hoạt động không chính xác khi xảy ra hiện tượng tràn số (overflow). Các Bài tập 5.9 và 5.10 sẽ tìm hiểu hạn chế này cũng như cách khắc phục nó. Ví dụ HDL 5.3 minh họa cách sử dụng các phép toán so sánh khác nhau cho các số không dấu, và Hình 5.13 biểu diễn phần cứng được tổng hợp tương ứng.

Hình 5.12 Bộ so sánh số có dấu N-bit

Ví dụ HDL 5.3 BỘ SO SÁNH (COMPARATORS)

SystemVerilog:
module comparators #(parameter N = 8)
    (input logic [N-1:0] a, b,
     output logic eq, neq, lt, lte, gt, gte);

    assign eq  = (a == b);
    assign neq = (a != b);
    assign lt  = (a < b);
    assign lte = (a <= b);
    assign gt  = (a > b);
    assign gte = (a >= b);
endmodule

VHDL:
library IEEE; use IEEE.STD_LOGIC_1164.ALL;

entity comparators is
    generic(N: integer := 8);
    port(a, b: in STD_LOGIC_VECTOR(N-1 downto 0);
         eq, neq, lt, lte, gt, gte: out STD_LOGIC);
end;

architecture synth of comparators is
begin
    eq  <= '1' when (a = b) else '0';
    neq <= '1' when (a /= b) else '0';
    lt  <= '1' when (a < b) else '0';
    lte <= '1' when (a <= b) else '0';
    gt  <= '1' when (a > b) else '0';
    gte <= '1' when (a >= b) else '0';
end;

Hình 5.13 Các bộ so sánh được tổng hợp (Synthesized comparators)

TRANG 262 | CHƯƠNG NĂM | Các Khối Xây Dựng Kỹ Thuật Số

Ví dụ HDL 5.4 BỘ ĐẾM (COUNTER)

SystemVerilog
module counter #(parameter N = 8)
    (input logic clk,
     input logic reset,
     output logic [N-1:0] q);

  always_ff @(posedge clk, posedge reset)
    if (reset) q <= 0;
    else q <= q + 1;
endmodule

VHDL
library IEEE; use IEEE.STD_LOGIC_1164.ALL;
use IEEE.NUMERIC_STD_UNSIGNED.ALL;

entity counter is
  generic(N: integer := 8);
  port(clk, reset: in STD_LOGIC;
       q: out STD_LOGIC_VECTOR(N-1 downto 0));
end;

architecture synth of counter is
begin
  process(clk, reset) begin
    if reset then q <= (OTHERS => '0');
    elsif rising_edge(clk) then q <= q + '1';
    end if;
  end process;
end;

Hình 5.34 Bộ đếm được tổng hợp

Ví dụ 5.7 BỘ DAO ĐỘNG ĐIỀU KHIỂN BẰNG KỸ THUẬT SỐ
Giả sử bạn có một xung nhịp 50 MHz và muốn tạo ra ngõ ra 500 Hz. Hãy xem xét việc sử dụng bộ đếm N = 24-bit hoặc 32-bit. Bạn nên chọn giá trị p bằng bao nhiêu và có thể tiến gần đến tần số 500 Hz ở mức độ nào?

Lời giải Chúng ta muốn p/2^N = 500 Hz/50 MHz = 0.001. Nếu N = 24, chọn p = 168 để thu được fout = 500.68 Hz. Nếu N = 32, chọn p = 42950 để thu được fout = 500.038 Hz.

Các loại bộ đếm khác, chẳng hạn như bộ đếm Lên/Xuống (Up/Down counters), được tìm hiểu trong các Bài tập từ 5.51 đến 5.54.

5.4.2 Thanh Ghi Dịch
Một thanh ghi dịch có một xung nhịp clk, một ngõ vào nối tiếp Sin, một ngõ ra nối tiếp Sout, và N ngõ ra song song QN-1:0, như được trình bày trong Hình 5.35. Tại mỗi cạnh lên của xung nhịp, một bit mới sẽ được dịch vào từ Sin và tất cả các nội dung tiếp theo sẽ được dịch về phía trước. Bit cuối cùng trong thanh ghi dịch có sẵn tại ngõ ra Sout.

Hình 5.35 Ký hiệu thanh ghi dịch

Trang 264 | CHƯƠNG NĂM: Các khối xây dựng kỹ thuật số

Ví dụ HDL 5.5: THANH GHI DỊCH CÓ NẠP SONG SONG

SystemVerilog:
module shiftreg #(parameter N = 8)
  (input logic clk,
   input logic reset, load,
   input logic sin,
   input logic [N-1:0] d,
   output logic [N-1:0] q,
   output logic sout);

  always_ff @(posedge clk, posedge reset)
    if (reset) q <= 0;
    else if (load) q <= d;
    else q <= {q[N-2:0], sin};

  assign sout = q[N-1];
endmodule

VHDL:
library IEEE; use IEEE.STD_LOGIC_1164.ALL;

entity shiftreg is
  generic(N: integer := 8);
  port(clk, reset: in STD_LOGIC;
       load, sin: in STD_LOGIC;
       d: in STD_LOGIC_VECTOR(N-1 downto 0);
       q: out STD_LOGIC_VECTOR(N-1 downto 0);
       sout: out STD_LOGIC);
end;

architecture synth of shiftreg is
begin
  process(clk, reset) begin
    if reset = '1' then q <= (OTHERS => '0');
    elsif rising_edge(clk) then
      if load then q <= d;
      else q <= q(N-2 downto 0) & sin;
      end if;
    end if;
  end process;

  sout <= q(N-1);
end;

Hình 5.38: Mạch thanh ghi dịch sau khi tổng hợp (Synthesized shiftreg)

Hình 5.39: Flip-flop có thể quét (Scannable flip-flop): (a) sơ đồ nguyên lý, (b) ký hiệu, và (c) thanh ghi N-bit có thể quét.

5.6 Mảng Logic | 273

Ví dụ HDL 5.6 Bộ nhớ RAM

SystemVerilog
module ram #(parameter N = 6, M = 32)
  (input logic clk,
   input logic we,
   input logic [N-1:0] adr,
   input logic [M-1:0] din,
   output logic [M-1:0] dout);

  logic [M-1:0] mem [2**N-1:0];

  always_ff @(posedge clk)
    if (we) mem [adr] <= din;

  assign dout = mem[adr];
endmodule

VHDL
library IEEE; use IEEE.STD_LOGIC_1164.ALL;
use IEEE.NUMERIC_STD_UNSIGNED.ALL;

entity ram_array is
  generic(N: integer := 6; M: integer := 32);
  port(clk,
       we: in STD_LOGIC;
       adr: in STD_LOGIC_VECTOR(N-1 downto 0);
       din: in STD_LOGIC_VECTOR(M-1 downto 0);
       dout: out STD_LOGIC_VECTOR(M-1 downto 0));
end;

architecture synth of ram_array is
  type mem_array is array ((2**N-1) downto 0)
    of STD_LOGIC_VECTOR (M-1 downto 0);
  signal mem: mem_array;
begin
  process(clk) begin
    if rising_edge(clk) then
      if we then mem(TO_INTEGER(adr)) <= din;
      end if;
    end if;
  end process;

  dout <= mem(TO_INTEGER(adr));
end;

Hình 5.55 Mạch RAM được tổng hợp

...thực hiện bất kỳ chức năng nào mà người dùng không cần phải đấu nối dây theo những cách cụ thể. Cấu trúc đồng đều giúp đơn giản hóa việc thiết kế. Các mảng logic được sản xuất hàng loạt với số lượng lớn nên có giá thành rẻ. Các công cụ phần mềm cho phép người dùng ánh xạ các thiết kế logic lên các mảng này. Hầu hết các mảng logic cũng có thể tái cấu hình, cho phép sửa đổi thiết kế mà không cần thay thế phần cứng. Khả năng tái cấu hình rất có giá trị trong quá trình phát triển và cũng hữu ích khi triển khai thực tế vì hệ thống có thể được nâng cấp chỉ bằng cách tải xuống cấu hình mới.
    Mục này giới thiệu hai loại mảng logic: mảng logic lập trình được (PLA) và mảng cổng lập trình được dạng trường (FPGA).

274   CHƯƠNG NĂM   Các khối xây dựng kỹ thuật số

Ví dụ HDL 5.7  ROM (Bộ nhớ chỉ đọc)

[SystemVerilog]
module rom(input logic [1:0] adr,
           output logic [2:0] dout);

  always_comb
    case(adr)
      2'b00: dout = 3'b011;
      2'b01: dout = 3'b110;
      2'b10: dout = 3'b100;
      2'b11: dout = 3'b010;
    endcase
endmodule

[VHDL]
library IEEE; use IEEE.STD_LOGIC_1164.all;

entity rom is
  port(adr: in STD_LOGIC_VECTOR(1 downto 0);
       dout: out STD_LOGIC_VECTOR(2 downto 0));
end;

architecture synth of rom is
begin
  process(all) begin
    case adr is
      when "00" => dout <= "011";
      when "01" => dout <= "110";
      when "10" => dout <= "100";
      when "11" => dout <= "010";
      when others => dout <= "---";
    end case;
  end process;
end;


Ví dụ HDL 5.8  TẬP THANH GHI (REGISTER FILE)

[SystemVerilog]
module regfile(input logic clk,
               input logic we3,
               input logic [5:0] a1, a2, a3,
               input logic [31:0] wd3,
               output logic [31:0] rd1, rd2);

  logic [31:0] rf[31:0];
  // tập thanh ghi có 3 cổng (three-ported register file)
  // đọc tổ hợp qua hai cổng (A1/RD1, A2/RD2)
  // ghi vào cổng thứ ba tại sườn lên của xung nhịp (A3/WD3/WE3)
  // thanh ghi 0 được nối cứng về giá trị 0

  always_ff @(posedge clk)
    if (we3) rf[a3] <= wd3;

  assign rd1 = (a1 != 0) ? rf[a1] : 0;
  assign rd2 = (a2 != 0) ? rf[a2] : 0;
endmodule

[VHDL]
library IEEE;
use IEEE.STD_LOGIC_1164.all;
use IEEE.NUMERIC_STD_UNSIGNED.all;

entity regfile is
  port(clk: in STD_LOGIC;
       we3: in STD_LOGIC;
       a1, a2, a3: in STD_LOGIC_VECTOR(5 downto 0);
       wd3: in STD_LOGIC_VECTOR(31 downto 0);
       rd1, rd2: out STD_LOGIC_VECTOR(31 downto 0));
end;

architecture behave of regfile is
  type ramtype is array (31 downto 0) of STD_LOGIC_VECTOR
                                         (31 downto 0);
  signal mem: ramtype;
begin
  -- tập thanh ghi có 3 cổng (three-ported register file)
  -- đọc tổ hợp qua hai cổng (A1/RD1, A2/RD2)
  -- ghi vào cổng thứ ba tại sườn lên của xung nhịp (A3/WD3/WE3)
  -- thanh ghi 0 được nối cứng về giá trị 0
  process(clk) begin
    if rising_edge(clk) then
      if we3 = '1' then mem(to_integer(a3)) <= wd3;
      end if;
    end if;
  end process;
  process(a1, a2) begin
    if (to_integer(a1) = 0) then rd1 <= X"00000000";
    else rd1 <= mem(to_integer(a1));
    end if;
    if (to_integer(a2) = 0) then rd2 <= X"00000000";
    else rd2 <= mem(to_integer(a2));
    end if;
  end process;
end;
